// VaultServer is the server API for Vault service.
// All implementations must embed UnimplementedVaultServer
// for forward compatibility.
//
// Vault is the paid immutable backup control plane.
// Cluster I/O uses open-core NodeStorage / Controller RPCs (kcore-rust
// proto/node.proto and proto/controller.proto); this service owns policies,
// jobs, repository targets, restore, and verify.
type VaultServer interface {
	// Status and licence
	GetVaultStatus(context.Context, *GetVaultStatusRequest) (*GetVaultStatusResponse, error)
	// Targets (fs / s3 repositories)
	ApplyTarget(context.Context, *ApplyTargetRequest) (*ApplyTargetResponse, error)
	GetTarget(context.Context, *GetTargetRequest) (*GetTargetResponse, error)
	ListTargets(context.Context, *ListTargetsRequest) (*ListTargetsResponse, error)
	DeleteTarget(context.Context, *DeleteTargetRequest) (*DeleteTargetResponse, error)
	// Policies
	ApplyBackupPolicy(context.Context, *ApplyBackupPolicyRequest) (*ApplyBackupPolicyResponse, error)
	GetBackupPolicy(context.Context, *GetBackupPolicyRequest) (*GetBackupPolicyResponse, error)
	ListBackupPolicies(context.Context, *ListBackupPoliciesRequest) (*ListBackupPoliciesResponse, error)
	DeleteBackupPolicy(context.Context, *DeleteBackupPolicyRequest) (*DeleteBackupPolicyResponse, error)
	// Jobs
	CreateBackupJob(context.Context, *CreateBackupJobRequest) (*CreateBackupJobResponse, error)
	GetBackupJob(context.Context, *GetBackupJobRequest) (*GetBackupJobResponse, error)
	ListBackupJobs(context.Context, *ListBackupJobsRequest) (*ListBackupJobsResponse, error)
	CancelBackupJob(context.Context, *CancelBackupJobRequest) (*CancelBackupJobResponse, error)
	CreateRestoreJob(context.Context, *CreateRestoreJobRequest) (*CreateRestoreJobResponse, error)
	GetRestoreJob(context.Context, *GetRestoreJobRequest) (*GetRestoreJobResponse, error)
	ListRestoreJobs(context.Context, *ListRestoreJobsRequest) (*ListRestoreJobsResponse, error)
	// Copy the instant-recovery overlay onto a cluster volume and close the NBD export.
	FinalizeInstantRecovery(context.Context, *FinalizeInstantRecoveryRequest) (*FinalizeInstantRecoveryResponse, error)
	CreateVerifyJob(context.Context, *CreateVerifyJobRequest) (*CreateVerifyJobResponse, error)
	GetVerifyJob(context.Context, *GetVerifyJobRequest) (*GetVerifyJobResponse, error)
	ListVerifyJobs(context.Context, *ListVerifyJobsRequest) (*ListVerifyJobsResponse, error)
	// Catalog
	ListBackups(context.Context, *ListBackupsRequest) (*ListBackupsResponse, error)
	GetBackup(context.Context, *GetBackupRequest) (*GetBackupResponse, error)
	// DR: rebuild catalog rows from signed manifests in a target repository.
	ImportCatalog(context.Context, *ImportCatalogRequest) (*ImportCatalogResponse, error)
	// Replication: copy every object of one target repository into another.
	CreateReplicationJob(context.Context, *CreateReplicationJobRequest) (*CreateReplicationJobResponse, error)
	GetReplicationJob(context.Context, *GetReplicationJobRequest) (*GetReplicationJobResponse, error)
	ListReplicationJobs(context.Context, *ListReplicationJobsRequest) (*ListReplicationJobsResponse, error)
	// Removes the job row. Objects already copied stay until retention and GC.
	DeleteReplicationJob(context.Context, *DeleteReplicationJobRequest) (*DeleteReplicationJobResponse, error)
	// Garbage collection of unreferenced, unlocked packs.
	RunGarbageCollection(context.Context, *RunGarbageCollectionRequest) (*RunGarbageCollectionResponse, error)
	// Licence (advisory in v1; enforce is a config flag)
	InstallLicence(context.Context, *InstallLicenceRequest) (*InstallLicenceResponse, error)
	GetLicence(context.Context, *GetLicenceRequest) (*GetLicenceResponse, error)
	// Live event stream. Clients resume with since_seq (the last seq they applied).
	WatchEvents(*WatchEventsRequest, grpc.ServerStreamingServer[VaultEvent]) error
	ListEvents(context.Context, *ListEventsRequest) (*ListEventsResponse, error)
	CancelRestoreJob(context.Context, *CancelRestoreJobRequest) (*CancelRestoreJobResponse, error)
	CancelVerifyJob(context.Context, *CancelVerifyJobRequest) (*CancelVerifyJobResponse, error)
	// Cluster inventory cached by the coordinator, with protection status.
	ListInventory(context.Context, *ListInventoryRequest) (*ListInventoryResponse, error)
	GetDashboardSummary(context.Context, *GetDashboardSummaryRequest) (*GetDashboardSummaryResponse, error)
	ListNotifications(context.Context, *ListNotificationsRequest) (*ListNotificationsResponse, error)
	AckNotification(context.Context, *AckNotificationRequest) (*AckNotificationResponse, error)
	// Read-only file restore of one backed-up volume.
	OpenFileRestore(context.Context, *OpenFileRestoreRequest) (*OpenFileRestoreResponse, error)
	ListDir(context.Context, *ListDirRequest) (*ListDirResponse, error)
	GetFile(context.Context, *GetFileRequest) (*GetFileResponse, error)
	DownloadArchive(*DownloadArchiveRequest, grpc.ServerStreamingServer[GetFileResponse]) error
	CloseFileRestore(context.Context, *CloseFileRestoreRequest) (*CloseFileRestoreResponse, error)
	// Appliance settings the dashboard edits (SMTP, webhooks, schedules).
	GetSettings(context.Context, *GetSettingsRequest) (*GetSettingsResponse, error)
	ApplySettings(context.Context, *ApplySettingsRequest) (*ApplySettingsResponse, error)
	mustEmbedUnimplementedVaultServer()
}

